-- RightPrice database, stage 1 of the rebuild (27 Nov 2026): what the app kept in files, moved in as it is.
--
-- Applied once, at start, by store.py, which records it in schema_migration. One text for PostgreSQL and SQLite:
-- the words in @...@ are the only ones that differ, and store.py fills them in:
--   @ID@    a row number given by the database   PostgreSQL: bigint generated by default as identity primary key
--                                                 SQLite:     integer primary key autoincrement
--   @BLOB@  a file kept whole                    PostgreSQL: bytea      SQLite: blob
--   @REAL@  a number                             PostgreSQL: double precision   SQLite: real
-- Times are kept as text in ISO form (2026-11-27T15:02:11), as the files kept them.
--
-- The tables of the later stages (Fab groups, purchase history, users and roles, dated rates, the benchmark) are in
-- db/schema.sql, the full design; each arrives in its own numbered file when its stage is built.

-- what each kind of data is at: the number goes up with every change, and the screens' memory keys on it
CREATE TABLE store_state (
    kind     TEXT PRIMARY KEY,                -- rates | list | negotiations | seen | sheets
    version  BIGINT NOT NULL
);
INSERT INTO store_state (kind, version) VALUES ('rates', 0), ('list', 0), ('negotiations', 0), ('seen', 0), ('sheets', 0);

CREATE TABLE store_meta (
    key    TEXT PRIMARY KEY,                  -- 'list_columns': the fabric list's columns, in the order the file had them
    value  TEXT NOT NULL
);

-- the copying in of the files, once, when DATABASE_URL is first set. The files are only read, never changed.
CREATE TABLE import_run (
    id           @ID@,
    started_at   TEXT NOT NULL,
    finished_at  TEXT NOT NULL,
    folder       TEXT NOT NULL,               -- where the files were (RIGHTPRICE_DATA)
    files        TEXT NOT NULL,               -- JSON: each file's name, size, SHA-256 and rows, as it was when copied
    checked      TEXT NOT NULL                -- JSON: what was compared, files against database, and that it was equal
);

-- the rate master: every saved version, the whole workbook, exactly the Excel file the app has always read.
-- The latest is the one in use; the earlier ones are the dated copies (no file is ever overwritten).
CREATE TABLE rate_version (
    id          @ID@,
    created_at  TEXT NOT NULL,
    created_by  TEXT NOT NULL DEFAULT '',     -- the signed-in person, where there is one
    reason      TEXT NOT NULL,                -- 'Copied in from Rate_Master.xlsx', 'Table edited: Yarn_Rates', 'Mill cost sheet drafts applied' ...
    workbook    @BLOB@ NOT NULL,
    sha256      TEXT NOT NULL
);

-- the fabric list (costing_log.csv): one row per fabric costed here, from Cost a fabric or an upload.
-- Each cell is kept as the text the list file held, so the screens read every row exactly as before; the costing saved
-- with the row ('costing') carries the rate version it was worked on. A removed row is kept, marked.
CREATE TABLE quote (
    id                  @ID@,                 -- the order on the list
    legacy_id           TEXT,                 -- the row's Id, as the screens and the tracker's keys use it
    saved_on            TEXT,
    fabric_code         TEXT,
    description         TEXT,
    supplier            TEXT,
    should_cost_per_m   TEXT,                 -- the should-cost when the row was saved (the list re-costs on today's rates)
    should_cost_per_kg  TEXT,
    quoted_per_m        TEXT,
    gap_per_m           TEXT,
    gap_pct             TEXT,
    choices             TEXT,                 -- JSON: the costing choices
    costing             TEXT,                 -- JSON: the costing when saved (total, groups, rates used)
    sheet_row           TEXT,                 -- JSON: the mill's own columns, untouched
    problems            TEXT,                 -- JSON: why it could not be costed
    notes               TEXT,                 -- JSON
    upload              TEXT,                 -- which file it came in with
    extra               TEXT NOT NULL DEFAULT '{}',   -- JSON: any other column the file had
    rate_version_id     BIGINT REFERENCES rate_version(id),   -- the rates 'costing' was worked on; empty for rows copied in from the file
    added_at            TEXT NOT NULL,
    added_by            TEXT NOT NULL DEFAULT '',
    removed_at          TEXT,
    removed_by          TEXT
);
CREATE INDEX quote_legacy_id ON quote (legacy_id);

-- the negotiation tracker (negotiations.json): one row per fabric, and its steps
CREATE TABLE negotiation (
    id      @ID@,
    key     TEXT NOT NULL UNIQUE,             -- 'Fabric list|<Id>' or 'Purchase orders|<code>'
    fields  TEXT NOT NULL DEFAULT '{}'        -- JSON: code, supplier, description, source, metres, should-cost, row price
);
CREATE TABLE negotiation_step (
    id               @ID@,                    -- the order the steps were recorded in
    negotiation_key  TEXT NOT NULL REFERENCES negotiation(key),
    step_id          TEXT NOT NULL,           -- the step's id, as the screens use it
    at               TEXT,                    -- when it was recorded
    step_date        TEXT,                    -- the date the person gave
    kind             TEXT,                    -- Mill's quote | Our counter | Mill's revised quote | Agreed
    price            @REAL@,                  -- rupees per metre
    note             TEXT,
    recorded_by      TEXT,                    -- the signed-in person, or 'AI assistant'
    extra            TEXT NOT NULL DEFAULT '{}',
    removed_at       TEXT,                    -- a removed step is kept, for the fabric's log
    removed_by       TEXT,
    removed_seq      BIGINT                   -- the order steps were removed in
);
CREATE INDEX negotiation_step_key ON negotiation_step (negotiation_key);

-- quote alerts marked seen (alerts_seen.json): shared, seen by one is seen by all
CREATE TABLE alert_seen (
    quote_id  TEXT PRIMARY KEY,               -- the fabric list row's Id
    seen_at   TEXT NOT NULL,
    seen_by   TEXT NOT NULL DEFAULT ''
);

-- mill cost sheet rows brought in (cost_sheets.json), one per fabric a mill priced
CREATE TABLE cost_sheet_row (
    id   @ID@,
    row  TEXT NOT NULL                        -- JSON: the mill's own figures, as read from its sheet
);
